//! Python data formats reproduced in Rust, for state that Python LiteLLM writes and reads.
//!
//! Each module mirrors one Python operation over plain data values, and its tests replay
//! fixtures generated by that operation in CPython (`scripts/generate_fixtures.py`):
//!
//! | Module | Python operation |
//! |---|---|
//! | [`literal`] | `ast.literal_eval(text)` |
//! | [`repr`] | `repr(value)` and `str(value)`, also of one `str` |
//! | [`reprlib`] | `reprlib.repr(value)` |
//! | [`json`] | `json.dumps(value)`, `json.loads(text)`, `type(json.loads(text)).__name__`, and `str()` and `==` of loaded values |
//! | [`pickle`] | `pickle.loads(data)` and `pickle.dumps(value)` for plain data |
//! | [`truthy`] | `bool(value)`, also straight off a `serde_json` value, and `a or b or ...` |
//! | [`number`] | `int(text)`, `float(text)`, `int(value)` and `float(value)` of loaded values, `sum(floats)`, `int(seconds)` as a `Duration`, and `str()` of an `int` or `float` |
//! | [`format`] | `format(value, f".{precision}f")` and `format(value, f".{precision}%")` |
//! | [`unicode`] | `str.isspace()` and `unicodedata.category()` for one character, and whether `str.encode("latin-1")` succeeds |
//! | [`pydantic`] | `TypeAdapter(bool)` and `TypeAdapter(int)` lax validation |
//! | [`urllib`] | `urllib.parse.quote(text, safe=safe)` and `urllib.parse.urlsplit(url)` |
//! | [`base64`] | `base64.b64decode(text, validate=True)` |
//! | [`datetime`] | `datetime.fromtimestamp(seconds, timezone.utc)` fields and `datetime.fromisoformat(text)` |
//! | [`flags`] | LiteLLM's own text-to-bool helpers, such as `str_to_bool` and `_redis._str_to_bool` |
//! | [`lenient`] | how Python reads an unvalidated config value: `value is True`, or a value of the expected shape |
//!
//! [`Value`] is the closed data model these formats share. Live Python objects
//! (descriptors, `__bool__`, `__str__`, callbacks) are out of scope: those belong to the
//! PyO3 boundary in `litellm-python-bridge`, which runs the real protocol.
//!
//! Known limits, each pinned by a test:
//! - `set` iteration order follows Python's hash order, which this crate does not model
//!   (string hashes are randomized per process). Sets keep their literal order.
//! - `str` values are Rust `String`s, so lone surrogates cannot be represented.
//! - [`pickle::loads`] decodes `tuple`, `set`, and `frozenset` as lists.
//! - [`number`] reads ASCII digits only, while Python's `int` and `float` accept any Unicode decimal digit.

pub mod base64;
pub mod datetime;
mod error;
pub mod flags;
pub mod format;
pub mod json;
pub mod lenient;
pub mod literal;
pub mod number;
pub mod pickle;
pub mod pydantic;
pub mod repr;
pub mod reprlib;
pub mod truthy;
pub mod unicode;
pub mod urllib;
mod value;

pub use error::Error;
pub use num_bigint::BigInt;
pub use value::Value;

/// Nesting limit for the decoders, which recurse. It keeps untrusted persisted data from
/// overflowing the Rust stack, and is deliberately stricter than CPython, whose parser takes
/// about 200 nested brackets and whose unpickler has no limit.
pub const MAX_DEPTH: usize = 128;
